package com.spai.portal.audit.domain;import java.time.OffsetDateTime;import javax.persistence.*;@Entity @Table(name="audit_log")public class AuditLog{@Id private String id;@Column(name="actor_id")private String actorId;@Column(nullable=false)private String action;@Column(name="target_type",nullable=false)private String targetType;@Column(name="target_id",nullable=false)private String targetId;@Column(name="before_data",columnDefinition="text")private String beforeData;@Column(name="after_data",columnDefinition="text")private String afterData;private String ip;@Column(name="created_at",nullable=false)private OffsetDateTime createdAt=OffsetDateTime.now();public String getId(){return id;}public void setId(String id){this.id=id;}public String getActorId(){return actorId;}public void setActorId(String actorId){this.actorId=actorId;}public String getAction(){return action;}public void setAction(String action){this.action=action;}public String getTargetType(){return targetType;}public void setTargetType(String targetType){this.targetType=targetType;}public String getTargetId(){return targetId;}public void setTargetId(String targetId){this.targetId=targetId;}public String getBeforeData(){return beforeData;}public void setBeforeData(String beforeData){this.beforeData=beforeData;}public String getAfterData(){return afterData;}public void setAfterData(String afterData){this.afterData=afterData;}public String getIp(){return ip;}public void setIp(String ip){this.ip=ip;}public OffsetDateTime getCreatedAt(){return createdAt;}public void setCreatedAt(OffsetDateTime createdAt){this.createdAt=createdAt;}}
